    Returns False otherwise.
    """
    if x < 0:
        return False
    if x == 0:
        return False
    if x == 1:
        return True
    if x == 0:
        return False

    # Check if x is a simple power of n
    # n**int(x) should equal x
    if n > 0:
        exponent = int(x)
        if n ** exponent == x:
            return True
    else:
        return False
